# Reference-domain endpoint grid, including nominally invalid adjacent values.
suppressPackageStartupMessages(library(univariateML,lib.loc='/tmp/umvl-p0lib'))
cfg<-list(pois=list(f=stats::dpois,p=c(lambda=2),x=0:3,ends=list(lambda=c(-.1,0,Inf))),geom=list(f=stats::dgeom,p=c(prob=.5),x=0:3,ends=list(prob=c(-.1,0,1,1.1))),nbinom=list(f=stats::dnbinom,p=c(size=2,prob=.4),x=0:3,ends=list(size=c(-.1,0,Inf),prob=c(-.1,0,1,1.1))),zip=list(f=extraDistr::dzip,p=c(lambda=2,pi=.3),x=0:3,ends=list(lambda=c(-.1,0,Inf),pi=c(-.1,0,1,1.1))),zinb=list(f=extraDistr::dzinb,p=c(size=2,prob=.4,pi=.3),x=0:3,ends=list(size=c(-.1,0,Inf),prob=c(-.1,0,1,1.1),pi=c(-.1,0,1,1.1))),zmpois=list(f=actuar::dzmpois,p=c(lambda=2,p0=.3),x=0:3,ends=list(lambda=c(-.1,0,Inf),p0=c(-.1,0,1,1.1))),ztpois=list(f=actuar::dztpois,p=c(lambda=2),x=1:4,ends=list(lambda=c(-.1,0,Inf))),zmgeom=list(f=actuar::dzmgeom,p=c(prob=.4,p0=.3),x=0:3,ends=list(prob=c(-.1,0,1,1.1),p0=c(-.1,0,1,1.1))),ztgeom=list(f=actuar::dztgeom,p=c(prob=.4),x=1:4,ends=list(prob=c(-.1,0,1,1.1))),zmnbinom=list(f=actuar::dzmnbinom,p=c(size=2,prob=.4,p0=.3),x=0:3,ends=list(size=c(-.1,0,Inf),prob=c(-.1,0,1,1.1),p0=c(-.1,0,1,1.1))),ztnbinom=list(f=actuar::dztnbinom,p=c(size=2,prob=.4),x=1:4,ends=list(size=c(-.1,0,Inf),prob=c(-.1,0,1,1.1))),zmlogarithmic=list(f=actuar::dzmlogarithmic,p=c(prob=.4,p0=.3),x=0:3,ends=list(prob=c(-.1,0,1,1.1),p0=c(-.1,0,1,1.1))),lgser=list(f=extraDistr::dlgser,p=c(theta=.9),x=1:4,ends=list(theta=c(-.1,0,1,1.1))),pig=list(f=actuar::dpoisinvgauss,p=c(mean=2,shape=3),x=0:3,ends=list(mean=c(-.1,0,Inf),shape=c(-.1,0,Inf))))
rows<-list();i<-0L
for(id in names(cfg)) for(p in names(cfg[[id]]$ends)) for(v in cfg[[id]]$ends[[p]]) { a<-cfg[[id]]; q<-a$p;q[p]<-v; res<-suppressWarnings(tryCatch(do.call(a$f,c(list(x=a$x),as.list(q))),error=function(e) rep(NA_real_,length(a$x)))); i<-i+1L; rows[[i]]<-data.frame(id=id,parameter=p,value=v,x=paste(a$x,collapse=';'),density=paste(format(res,digits=9,trim=TRUE),collapse=';'),valid=all(is.finite(res))&&all(res>=0)&&all(res<=1)) }
write.csv(do.call(rbind,rows),'dev/research/evaluations/2026-10-29-p0-counts/domain.csv',row.names=FALSE)
